mapper.sql:
FROM t_record r LEFT JOIN t_category c ON c.id = r.category_id
r.deleted_at IS NULL AND r.is_visible = 1 AND r.status = 'PENDING' AND r.type = #{condition.type} AND r.category_id = #{condition.categoryId}
AND (r.title LIKE #{condition.keywordPattern} ESCAPE '/' OR r.description LIKE #{condition.keywordPattern} ESCAPE '/')

mapper.select:
SELECT r.id, r.type, r.status, r.completed_at, r.title, r.category_id, c.name AS category_name,
       r.location, r.occurred_at, r.publisher_id, r.summary, r.created_at


LIMIT #{limit} OFFSET #{offset}

mapper.sql:
FROM t_record r
LEFT JOIN t_category c ON c.id = r.category_id

    r.deleted_at IS NULL
    AND r.publisher_id = #{condition.publisherId}
    AND r.type = #{condition.type}
    AND r.status = #{condition.status}

mapper.select:
SELECT r.id, r.title, r.description, r.category_id, r.location
FROM t_record r

    r.deleted_at IS NULL
    AND 
    AND r.type = #{type}
    AND r.category_id = #{categoryId}

ORDER BY r.created_at DESC, r.id DESC
LIMIT #{limit}

mapper.update:
UPDATE t_record
SET pair_state = #{state}
WHERE id = #{id} AND deleted_at IS NULL

UPDATE t_record
SET review_attempts = #{attempts}
WHERE id = #{id} AND deleted_at IS NULL AND review_state = 'PENDING'

mapper.select:
SELECT 
FROM t_record r
LEFT JOIN t_category c ON c.id = r.category_id
WHERE r.deleted_at IS NULL
  AND r.review_state = 'PENDING'
  AND r.review_manual_required = 0
  AND r.review_attempts < #{maxAttempts}
  AND r.created_at <= #{createdBefore}
ORDER BY r.created_at ASC, r.id ASC
LIMIT #{limit}
